package org.example;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.List;
import tools.jackson.core.type.TypeReference;
import tools.jackson.databind.json.JsonMapper;

public class App {
    private final HttpClient client;
    private static final JsonMapper jsonMapper = JsonMapper.builder().build();
    private static final String url = "http://localhost:8080/pessoas/";
    public App() {
        this.client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();
    }
    public void listarPessoas() {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .header("Accept", "application/json")
                .GET()
                .build();
        try {
            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

            if (response.statusCode() == 200) {
                List<Pessoa> pessoas = jsonMapper.readValue(response.body(), new TypeReference<List<Pessoa>>() {
                });
                pessoas.forEach(System.out::println);
            }
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
    public Pessoa listarPessoaPorID(long id) {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url + id))
                .header("Accept", "application/json")
                .GET()
                .build();
        try {
            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() == 200) {
                Pessoa p = jsonMapper.readValue(response.body(), Pessoa.class);
                System.out.println(p);
                return p;
            }
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
        return null;
    }
    public void cadastrarPessoa(Pessoa p) {
        String jsonBody = jsonMapper.writeValueAsString(p);
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(jsonBody))
                .build();
        try {
            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            switch (response.statusCode()) {
                case 201 -> System.out.println("Pessoa cadastrada com sucesso!\n" + response.body());
                default -> System.err.println("O servidor retornou um erro: " + response.statusCode());
            }
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
    public void excluirPessoa(long id) {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url + id))
                .timeout(Duration.ofSeconds(5))
                .DELETE()
                .build();
        try {
            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            switch (response.statusCode()) {
                case 204 -> System.out.println("Registro excluído com sucesso!");
                case 404 -> System.err.println("Erro: O registro com o ID " + id + " não foi encontrado.");
                default -> System.err.println("O servidor retornou um erro inesperado: " + response.statusCode());
            }
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();

        }
    }
    public void substituirPessoaPorCompleto(Pessoa pessoa) {
        String jsonBody = jsonMapper.writeValueAsString(pessoa);
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url + pessoa.id()))
                .header("Content-Type", "application/json")
                .timeout(Duration.ofSeconds(5))
                .PUT(HttpRequest.BodyPublishers.ofString(jsonBody))
                .build();
        try {
            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            switch (response.statusCode()) {
                case 204 -> System.out.println("Registro atualizado com sucesso!");
                case 404 -> System.err.println("Erro: O registro com o ID " + pessoa.id() + " não existe.");
                default -> {
                    System.err.println("O servidor retornou um erro: " + response.statusCode());
                    System.err.println(response.body());
                }
            }
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
    public void atualizarEmailPessoa(long id, String novoEmail) {
        Pessoa p = this.listarPessoaPorID(id);
        if (p != null) {
            Pessoa novaPessoa = new Pessoa(p.id(), p.nome(), novoEmail);
            String jsonBody = jsonMapper.writeValueAsString(novaPessoa);
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(url + id))
                    .header("Content-Type", "application/json")
                    .timeout(Duration.ofSeconds(5))
                    .method("PATCH", HttpRequest.BodyPublishers.ofString(jsonBody))
                    .build();
            try {
                HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
                switch (response.statusCode()) {
                    case 204 -> System.out.println("Registro atualizado com sucesso!");
                    case 400 ->
                            System.err.println("Erro: cliente enviou dados inválidos ou malformados\n" + response.body());
                    case 404 ->
                            System.err.println("Erro: O registro com o ID " + id + " não existe para ser atualizado.");
                    default -> {
                        System.err.println("O servidor retornou um erro: " + response.statusCode());
                        System.err.println(response.body());
                    }
                }
            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
    public static void main(String[] args) {
        App app = new App();
        app.listarPessoas();
        app.listarPessoaPorID(1);
        app.cadastrarPessoa(new Pessoa(0, "Joaquim", "joaquim@example.org"));
        app.excluirPessoa(1);

        app.atualizarEmailPessoa(2, "novo@example.org");
        app.substituirPessoaPorCompleto(new Pessoa(2, "Ana", "ana@example.com"));
    }
}
